import { ACTIVITY_TYPES, type ActivityType, type CalendarWorkoutRule } from '@motivation/shared';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import {
    CalendarWorkoutRulesService,
    calendarWorkoutRulesService as defaultService,
} from '../../../services/calendar-workout-rules.service.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { activityTypeLabel } from '../../health/health-utils.js';
import screenStyles from './calendar-workouts-settings-screen.css?inline';

documentStyleSheet(screenStyles);

/**
 * Story 402 — list, edit and remove the calendar workout rules. A rule is added most often from the
 * agenda's "Track as workout"; this is where a typo or a gym you left gets fixed.
 */
const template = document.createElement('template');
template.innerHTML = `
    <section class="calendar-workouts-settings">
        <p>Calendar events whose title contains one of these become adoptable workouts of that type. The first match wins.</p>
        <div class="calendar-workouts-settings__rules" data-testid="rules"></div>
        <p data-testid="empty" hidden>No rules — no calendar event is treated as a workout.</p>
        <div class="calendar-workouts-settings__actions">
            <button type="button" data-testid="add">Add rule</button>
            <button type="button" data-testid="save">Save</button>
            <span data-testid="saved" hidden>Saved ✓</span>
        </div>
        <pre class="screen-error" data-testid="error" hidden></pre>
    </section>
`;

export class CalendarWorkoutsSettingsScreen extends HTMLElement implements ScreenComponent {
    setLoading(): void {}
    setError(err: unknown): void { this.showError(err); }
    clearStatus(): void { this.showError(null); }

    private initialized = false;
    private readonly log = createComponentLogger('calendar-workouts-settings-screen');
    private service: CalendarWorkoutRulesService = defaultService;

    setService(service: CalendarWorkoutRulesService): void {
        this.service = service;
        if (this.initialized) void this.refresh();
    }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;

        const page = buildSectionPage(this, 'Calendar workouts', 'extra', '/extra');
        page.content.appendChild(template.content.cloneNode(true));

        this.queryEl('add').addEventListener('click', () => {
            this.appendRow({ match: '', type: 'workout' });
            this.markDirty();
        });
        this.queryEl('save').addEventListener('click', () => void this.handleSave());

        void this.refresh();
    }

    async refresh(): Promise<void> {
        try {
            this.renderRules(await this.service.getRules());
        } catch (error) {
            this.log.error('refresh failed:', error);
            this.showError(error);
        }
    }

    private renderRules(rules: readonly CalendarWorkoutRule[]): void {
        this.queryEl('rules').replaceChildren();
        for (const rule of rules) this.appendRow(rule);
        this.syncEmpty();
    }

    private appendRow(rule: CalendarWorkoutRule): void {
        const row = document.createElement('div');
        row.className = 'calendar-workouts-settings__rule';
        row.dataset.testid = 'rule';

        const match = document.createElement('input');
        match.type = 'text';
        match.value = rule.match;
        match.placeholder = 'e.g. Open Gym';
        match.setAttribute('aria-label', 'Events containing');
        match.dataset.testid = 'rule-match';
        match.addEventListener('input', () => this.markDirty());

        const type = document.createElement('select');
        type.setAttribute('aria-label', 'Type');
        type.dataset.testid = 'rule-type';
        for (const value of ACTIVITY_TYPES) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = activityTypeLabel(value);
            type.appendChild(option);
        }
        type.value = rule.type;
        type.addEventListener('change', () => this.markDirty());

        const remove = document.createElement('button');
        remove.type = 'button';
        remove.textContent = 'Remove';
        remove.dataset.testid = 'rule-remove';
        remove.addEventListener('click', () => {
            row.remove();
            this.syncEmpty();
            this.markDirty();
        });

        row.append(match, type, remove);
        this.queryEl('rules').appendChild(row);
        this.syncEmpty();
    }

    private readRows(): CalendarWorkoutRule[] {
        return [...this.querySelectorAll<HTMLElement>('[data-testid="rule"]')].map((row) => ({
            match: row.querySelector<HTMLInputElement>('[data-testid="rule-match"]')!.value.trim(),
            type: row.querySelector<HTMLSelectElement>('[data-testid="rule-type"]')!.value as ActivityType,
        }));
    }

    private async handleSave(): Promise<void> {
        this.showError(null);
        try {
            await this.service.saveRules(this.readRows());
            await this.refresh();
            this.queryEl('saved').hidden = false;
        } catch (error) {
            this.log.error('save failed:', error);
            this.showError(error);
        }
    }

    private markDirty(): void {
        this.queryEl('saved').hidden = true;
    }

    private syncEmpty(): void {
        this.queryEl('empty').hidden = this.querySelector('[data-testid="rule"]') !== null;
    }

    private queryEl(testid: string): HTMLElement {
        const el = this.querySelector<HTMLElement>(`[data-testid="${testid}"]`);
        if (!el) throw new Error(`calendar-workouts-settings: missing [data-testid="${testid}"]`);
        return el;
    }

    private showError(error: unknown): void {
        const el = this.querySelector<HTMLElement>('[data-testid="error"]');
        if (!el) {
            if (error !== null) throw error;
            return;
        }
        el.hidden = error === null;
        el.textContent = error === null ? '' : error instanceof Error ? `${error.message}\n${error.stack ?? ''}` : String(error);
    }
}

if (!customElements.get('calendar-workouts-settings-screen')) {
    customElements.define('calendar-workouts-settings-screen', CalendarWorkoutsSettingsScreen);
}
